'use strict';
const auditState={tab:'taiwan',query:'',gaps:false};
const auditTabs={taiwan:"taiwan · rutas",local:"Costa Rica / México",southamerica:"América del Sur",europe:"Suiza / España / Francia",'europe-north':"Alemania / los Países Bajos / Bélgica",'europe-south':"Italia / Portugal",southeastasia:"Asia del sureste",'asia-english':"Singapur / Hong Kong",eastasia:"Japón / China / Taiwán",africa:"África · rutas familiares",middleeast:"Oaé / Omán / Qatar / Arabia Saudita",continents:"los continentes",leagues:"las ligas y programas",exhibitions:"grandes exposiciones",added:"se ha añadido",remaining:"¿Qué queda?"};
const auditGateLabels={family:"con un adulto",adults_only:"Los niños del 6/9 no pueden",confirm_children:"el permiso de entrada de niños"};
function renderCompletenessAudit(){
  const root=$('#completeness-audit'),a=DATA.completeness_audit,n=a.counts;
  if(!$('#audit-body'))root.innerHTML=`<div class="audit-heading"><div><p class="section-kicker">AUDITORÍA DE COBERTURA · ${esc(a.checked)}</p><h3>El mundo está en la base.<br>Los huecos también se ven.</h3></div><span class="audit-status">el estudio continúa</span></div><p class="audit-verdict">${esc(a.conclusion)}</p><p class="audit-scope">${esc(a.scope)}</p><div class="audit-metrics">${[[n.league_profiles,"los perfiles de las ligas y programas",a.baseline.league_profiles],[n.competition_cards,"tarjetas de las competiciones",a.baseline.competition_cards],[n.major_exhibition_cards,"de las tarjetas de exposición",a.baseline.major_exhibition_cards],[n.countries_with_records,"países y territorios con registros",a.baseline.countries_with_records]].map(([count,label,before])=>`<div><strong>${count}</strong><span>${esc(label)}</span><small>${before} → ${count} después de la auditoría</small></div>`).join('')}</div><div class="audit-bias"><div><b>VEX · ${n.vex_cards} de ${n.competition_cards}</b><span>${(100*n.vex_cards/n.competition_cards).toFixed(1)}% de tarjetas de competición pertenecen a una red</span></div><div class="audit-bias-track" role="img" aria-label="la participación de VEX entre las tarjetas de competición ${(100*n.vex_cards/n.competition_cards).toFixed(1)} por ciento"><span style="width:${100*n.vex_cards/n.competition_cards}%"></span></div><p>Es la proporción de registros en la base. La complejidad del calendario mundial no se determina en este gráfico.</p></div><div class="audit-tabs" role="tablist" aria-label="sección de auditoría">${Object.entries(auditTabs).map(([id,label])=>`<button role="tab" id="audit-tab-${id}" data-audit-tab="${id}" aria-controls="audit-body">${esc(label)}${id==='added'?` <small>+${a.new_ids.length}</small>`:''}</button>`).join('')}</div><div class="audit-filters" id="audit-filters"><label>búsqueda en esta sección<input type="search" id="audit-search" placeholder="nombre, país o dirección"></label><label class="audit-gap-filter" id="audit-gap-label"><input type="checkbox" id="audit-gaps"> Sólo registros con especificaciones</label></div><p class="audit-list-count" id="audit-list-count" role="status"></p><div id="audit-body" role="tabpanel"></div><div class="audit-downloads"><a class="button secondary" href="downloads/STEM_completeness_audit.md" download>todo el informe · Markdown</a><a class="button secondary" href="downloads/STEM_completeness_audit.json" download>Inventario y espacios en blanco · JSON</a></div><details class="audit-boundaries"><summary>¿Qué significa esta verificación?</summary><ul>${a.caveats.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p>Todos ${n.cards} las tarjetas se guardan en las descargas de los auditos locales completados: ${n.fully_audited_countries} de ${DATA.coverage_summary.countries} de los países y territorios.</p><h4>diferencias de las fuentes primarias</h4>${a.source_issues.map(s=>`<p><b>${esc(s.name)}.</b> ${esc(s.status)}${s.official_alternative?` <a href="${esc(s.official_alternative)}" target="_blank" rel="noopener">la alternativa oficial</a>`:''}</p>`).join('')}</details>`;
  $$('[data-audit-tab]').forEach(b=>{const on=b.dataset.auditTab===auditState.tab;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});
  $('#audit-filters').hidden=['continents','taiwan','local','southamerica','europe','europe-north','europe-south','southeastasia','asia-english','eastasia','africa','middleeast'].includes(auditState.tab);$('#audit-gap-label').hidden=!['leagues','exhibitions'].includes(auditState.tab);
  $('#audit-search').value=auditState.query;$('#audit-gaps').checked=auditState.gaps;
  $('#audit-body').setAttribute('aria-labelledby','audit-tab-'+auditState.tab);
  renderAuditBody();
}
function auditMatches(value){return JSON.stringify(value).toLocaleLowerCase('es').includes(auditState.query.trim().toLocaleLowerCase('es'))}
function auditSource(url){return url?`<a class="audit-source" href="${esc(url)}" target="_blank" rel="noopener">Fuente oficial ↗</a>`:''}
function renderAuditBody(){
  const a=DATA.completeness_audit,box=$('#audit-body'),count=$('#audit-list-count');
  if(auditState.tab==='taiwan'){
    const t=a.focused_country,local=EVENTS.filter(e=>e.iso.includes(t.iso));
    count.textContent=`${local.length} las tarjetas de Taiwán · ${local.filter(e=>e.block==="Competiciones").length} de las competiciones / caminos · ${local.filter(e=>e.block==="Eventos").length} eventos · ${local.filter(e=>e.block==="Campamentos").length} programas`;
    box.innerHTML=`<div class="taiwan-intro"><p class="section-kicker">TAIWÁN · ITINERARIO PERSONAL</p><h4>Dos edades.<br>las diferentes formas de participar.</h4><p>${esc(t.family)}</p><p>${esc(t.conclusion)}</p><button class="button primary" data-taiwan-catalog="true">Todos ${local.length} las tarjetas de taiwanés</button></div><div class="taiwan-routes">${t.routes.map((r,i)=>`<article><span class="audit-index">${String(i+1).padStart(2,'0')}</span><h4>${esc(r.name)}</h4><p>${esc(r.detail)}</p><div class="taiwan-route-links">${r.ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return `<button data-open="${esc(id)}">${esc(e.title)} <span>↗</span></button>`}).join('')}</div></article>`).join('')}</div><p class="audit-footnote">${esc(t.language_result)}</p><details class="audit-boundaries"><summary>¿Qué más puedes comprobar antes de irte?</summary><ul>${t.open_questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>se comprobó la geografía real</h4>${t.rejected_geographies.map(x=>`<p><b>${esc(x.name)} → ${esc(x.actual_country)}.</b> ${esc(x.reason)}</p>`).join('')}</details><div class="audit-downloads"><a class="button secondary" href="downloads/STEM_Taiwan.md" download>taiwan · todo el informe</a><a class="button secondary" href="downloads/STEM_Taiwan.json" download>taiwan · datos con fuentes</a></div>`;
  } else if(auditState.tab==='local'){
    const t=a.local_focus,local=EVENTS.filter(e=>e.iso.some(i=>['CRI','MEX'].includes(i)));
    const eventLinks=ids=>ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return e?`<button data-open="${esc(id)}">${esc(e.title)} ↗</button>`:''}).join('');
    count.textContent=`${local.length} las tarjetas de Costa Rica y México · es un inventario de base, no un calendario local completo`;
    box.innerHTML=`<div class="taiwan-intro local-intro"><p class="section-kicker">CERCA DE CASA · ITINERARIOS PERSONALES</p><h4>El próximo lanzamiento.<br>Las vacaciones y el siguiente nivel.</h4><p>${esc(t.family)}</p><p>${esc(t.conclusion)}</p><div class="taiwan-route-links"><button class="button primary" data-country-catalog="CRI">todas las tarjetas de Costa Rica →</button><button class="button secondary" data-country-catalog="MEX">todas las tarjetas de México →</button></div></div>${renderEuropeFamilyPicks(t,eventLinks)}<div class="taiwan-routes local-routes">${t.routes.map((r,i)=>`<article><span class="audit-index">${String(i+1).padStart(2,'0')}</span><h4>${esc(r.name)}</h4><p>${esc(r.detail)}</p><div class="taiwan-route-links">${r.ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return `<button data-open="${esc(id)}">${esc(e.title)} <span>↗</span></button>`}).join('')}</div></article>`).join('')}</div><p class="audit-footnote">${esc(t.language_result)}</p><details class="audit-boundaries"><summary>condiciones que aún deben ser confirmadas.</summary><ul>${t.open_questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><div class="audit-downloads"><a class="button secondary" href="downloads/STEM_CostaRica_Mexico.md" download>Costa Rica / México · informe</a><a class="button secondary" href="downloads/STEM_CostaRica_Mexico.json" download>Costa Rica / México · datos</a></div>`;
  } else if(auditState.tab==='southamerica'){
    const t=a.south_america_focus,rows=EVENTS.filter(e=>e.iso.some(i=>t.isos.includes(i))),countries=COUNTRIES.filter(c=>t.isos.includes(c.iso));
    count.textContent=`${rows.length} las tarjetas de cinco direcciones comprobadas. Es un paso parcial, no es el calendario completo de América del Sur.`;
    box.innerHTML=`<div class="taiwan-intro south-america-intro"><p class="section-kicker">AMÉRICA DEL SUR · ITINERARIOS FAMILIARES</p><h4>Las vacaciones en el sur.<br>Su camino hacia la competición.</h4><p>${esc(t.family)}</p><p>${esc(t.conclusion)}</p><div class="taiwan-route-links">${countries.map(c=>`<button class="button secondary" data-country-catalog="${esc(c.iso)}">${esc(c.country)} →</button>`).join('')}</div></div><div class="taiwan-routes south-america-routes">${t.routes.map((r,i)=>`<article><span class="audit-index">${String(i+1).padStart(2,'0')}</span><h4>${esc(r.name)}</h4><p>${esc(r.detail)}</p><div class="taiwan-route-links">${r.ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return `<button data-open="${esc(id)}">${esc(e.title)} <span>↗</span></button>`}).join('')}</div></article>`).join('')}</div><p class="audit-footnote">${esc(t.language_result)}</p><details class="audit-boundaries"><summary>condiciones que aún deben ser confirmadas.</summary><ul>${t.open_questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><div class="audit-downloads"><a class="button secondary" href="downloads/STEM_South_America.md" download>América del Sur · informe</a><a class="button secondary" href="downloads/STEM_South_America.json" download>América del Sur · datos</a></div>`;
  } else if(auditState.tab==='europe'){
    renderEuropeFocus(box,count);
  } else if(auditState.tab==='europe-north'){
    renderEuropeFocus(box,count,DATA.north_europe_focus,'STEM_Europe_DEU_NLD_BEL');
  } else if(auditState.tab==='europe-south'){
    renderEuropeFocus(box,count,DATA.south_europe_focus,'STEM_Europe_ITA_PRT');
  } else if(auditState.tab==='eastasia'){
    renderEuropeFocus(box,count,DATA.east_asia_focus,'STEM_East_Asia_JPN_CHN_TWN');
  } else if(auditState.tab==='asia-english'){
    renderEuropeFocus(box,count,DATA.asia_english_focus,'STEM_Singapore_HongKong');
  } else if(auditState.tab==='southeastasia'){
    renderEuropeFocus(box,count,DATA.southeast_asia_focus,'STEM_Southeast_Asia');
  } else if(auditState.tab==='middleeast'){
    renderEuropeFocus(box,count,DATA.middleeast_focus,'STEM_Middle_East');
  } else if(auditState.tab==='africa'){
    renderEuropeFocus(box,count,DATA.africa_focus,'STEM_Africa');
  } else if(auditState.tab==='continents'){
    count.textContent="Se presentan seis continentes habitados; cada uno es parcialmente explorado.";
    const max=Math.max(...a.continents.map(c=>c.total));
    box.innerHTML=`<div class="audit-legend"><span class="comp">Competiciones</span><span class="expo">todas las exposiciones / eventos</span><span class="camp">campamento / formación</span></div><div class="audit-continents">${a.continents.map((c,i)=>`<article><div class="audit-continent-title"><span class="audit-index">0${i+1}</span><h4>${esc(c.name)}</h4><strong>${c.total}<small>fichas</small></strong></div><div class="audit-continent-bar" role="img" aria-label="${esc(c.name)}: ${c.competitions} competiciones, ${c.events} exposiciones y eventos, ${c.camps} campamentos"><span class="comp" style="width:${100*c.competitions/max}%"></span><span class="expo" style="width:${100*c.events/max}%"></span><span class="camp" style="width:${100*c.camps/max}%"></span></div><div class="audit-continent-counts"><span><b>${c.competitions}</b>competiciones</span><span><b>${c.major_exhibitions}</b>de las grandes exposiciones</span><span><b>${c.camps}</b>campamentos / programas</span></div><p class="audit-continent-countries">${c.countries_with_records} los países / territorios con registros · ${esc(c.status)}</p><details><summary>las demás direcciones</summary><p>${esc(c.remaining)}</p></details></article>`).join('')}</div><p class="audit-footnote">La longitud de las bandas  el número de tarjetas, la escala es igual para todos los continentes.${a.interregional_cards}América del Norte incluye América Central y la región caribeña. Antarctica: no se ha encontrado un calendario local relevante en el marco de la verificación.</p>`;
  } else if(auditState.tab==='leagues'){
    const all=a.league_inventory,rows=all.filter(g=>auditMatches(g)&&(!auditState.gaps||!g.cards||!g.future_dated));
    count.textContent=`${rows.length} de ${all.length} perfiles · ${all.filter(g=>!g.cards).length} sin tarjetas de calendario . ${all.filter(g=>g.cards&&!g.future_dated).length} con tarjetas, pero sin fechas exactas futuras.`;
    box.innerHTML=`<p class="audit-footnote">el perfil puede describir una familia con varias disciplinas. la presencia de tarjetas confirma la presencia en la base, no el calendario nacional completo. el filtro de especificaciones muestra la ausencia de etapas o fechas futuras.</p><div class="audit-inventory">${rows.map(g=>`<article><div><h4>${esc(g.name)}${g.new?"<small class=\"audit-new\">se ha añadido</small>":''}</h4><p>${esc(g.status)}</p><div class="audit-inventory-meta"><span>${g.cards} fichas</span><span class="${g.future_dated?'':'audit-unknown'}">${g.future_dated} con fechas futuras</span></div></div><div class="audit-row-actions"><button class="league-link" data-audit-league="${esc(g.id)}">edad y camino de selección</button>${auditSource(g.source)}</div></article>`).join('')}</div>`;
  } else if(auditState.tab==='exhibitions'){
    const all=a.exhibition_inventory,rows=all.filter(e=>auditMatches(e)&&(!auditState.gaps||!e.start||e.visitor_policy==='confirm_children')).sort((x,y)=>(x.start||'9999').localeCompare(y.start||'9999'));
    count.textContent=`${rows.length} de ${all.length} las tarjetas · las ediciones de una exposición se consideran separadas`;
    box.innerHTML=`<p class="audit-footnote">Esta es una lista editorial de las exposiciones de robótica, industria y AI / tech. La lista oficial general de todas las exposiciones más grandes no. El filtro de especificaciones muestra una fecha desconocida o la entrada de un niño.</p><div class="audit-inventory">${rows.map(e=>`<article><div><h4>${esc(e.name)}${e.new?"<small class=\"audit-new\">se ha añadido</small>":''}</h4><p>${esc(e.country)} · ${e.start?shortDate(e.start)+(e.end!==e.start?' — '+shortDate(e.end):''):"la siguiente fecha no se conoce"}</p><span class="audit-gate ${esc(e.visitor_policy)}">${esc(auditGateLabels[e.visitor_policy])}</span></div><div class="audit-row-actions"><button class="league-link" data-open="${esc(e.id)}">Permiso, edad y programa →</button>${auditSource(e.source)}</div></article>`).join('')}</div>`;
  } else if(auditState.tab==='added'){
    const all=EVENTS.filter(e=>a.new_ids.includes(e.id)),rows=all.filter(auditMatches);
    count.textContent=`${rows.length} de ${all.length} nuevas tarjetas · ${a.new_profiles.length} nuevos perfiles · fuentes y limitaciones  en cada tarjeta`;
    box.innerHTML=`<div class="audit-inventory">${rows.map(e=>`<article><div><p class="section-kicker">${esc(e.block)} · ${esc(e.id)}</p><h4>${esc(e.title)}</h4><p>${esc(e.country)} · ${e.start?shortDate(e.start)+(e.end!==e.start?' — '+shortDate(e.end):''):"las siguientes fechas no se han anunciado"}</p></div><div class="audit-row-actions"><button class="league-link" data-open="${esc(e.id)}">abrir la tarjeta →</button>${auditSource(e.source)}</div></article>`).join('')}</div>`;
  } else {
    const rows=a.known_backlog.filter(auditMatches);count.textContent=`${rows.length} de ${a.known_backlog.length} de las direcciones conocidas · lista de huecos también no es exhaustivo`;
    box.innerHTML=`<div class="audit-backlog">${rows.map((b,i)=>`<article><span class="audit-index">${String(i+1).padStart(2,'0')}</span><div><p class="section-kicker">${esc(b.kind)}</p><h4>${esc(b.name)}</h4><p>${esc(b.reason)}</p>${b.url?`<a class="audit-source" href="${esc(b.url)}" target="_blank" rel="noopener">página para la siguiente verificación</a>`:''}</div></article>`).join('')}</div><p class="audit-footnote">La falta de registro significa que el estudio está vacío. No prueba la falta de competiciones o exposiciones en el país.</p>`;
  }
  if(auditState.query&&!box.querySelector('article'))box.innerHTML="<p class=\"audit-empty\">No hay coincidencias. Trata de otro nombre o quita el filtro.</p>";
}
document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.auditTab){Object.assign(auditState,{tab:b.dataset.auditTab,query:'',gaps:false});renderCompletenessAudit()}
  if(b.dataset.taiwanCatalog){Object.assign(state,{league:'',block:'',query:'',kid:'',region:'',country:'TWN',theme:'',language:'',languageMode:'',campProjects:false,scope:'',participation:'',admission:'',evidence:'',visitorPolicy:'',dates:'',priority:false,excluded:true});setView('catalog')}
  if(b.dataset.countryCatalog){Object.assign(state,{league:'',block:'',query:'',kid:'',region:'',country:b.dataset.countryCatalog,theme:'',language:'',languageMode:'',campProjects:false,scope:'',participation:'',admission:'',evidence:'',visitorPolicy:'',dates:'',priority:false,excluded:true});setView('catalog')}
  if(b.dataset.auditLeague){Object.assign(leagueState,{tab:'guide',query:'',age:'',group:''});leagueState.opened.add(b.dataset.auditLeague);setView('leagues');const el=$('#league-'+b.dataset.auditLeague);el.scrollIntoView({behavior:'smooth',block:'start'});el.querySelector('summary').focus({preventScroll:true})}
});
document.addEventListener('input',e=>{if(e.target.id==='audit-search'){auditState.query=e.target.value;renderAuditBody()}});
document.addEventListener('change',e=>{if(e.target.id==='audit-gaps'){auditState.gaps=e.target.checked;renderAuditBody()}});
document.addEventListener('keydown',e=>{if(!e.target.dataset.auditTab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const ids=Object.keys(auditTabs),i=ids.indexOf(auditState.tab),next=e.key==='Home'?0:e.key==='End'?ids.length-1:(i+(e.key==='ArrowRight'?1:-1)+ids.length)%ids.length;auditState.tab=ids[next];auditState.query='';auditState.gaps=false;renderCompletenessAudit();$('#audit-tab-'+auditState.tab).focus()});
